const { native } = require('./config/_import.js')
const { logDir } = require('./config/log_dir.js')
const { conOptions } = require('./config/connection_options.js')

const path = require('path')
const logfilename = __filename.split(path.sep).pop().replace('.js', '.log')
conOptions.logfile = path.join(logDir, logfilename)

const globalName = '^isc.node.test'

const c = native.createConnection(conOptions)
const iris = c.createIris()
iris.set(1, globalName, 1)
iris.lock('S', 0, globalName, 1)
iris.unlock('S', globalName, 1)
iris.releaseAllLocks()
c.close()
